{
  "name": "@lidtop/opencode-review",
  "version": "0.2.0",
  "description": "Comment on the agent's diffs in OpenCode while it works, and send the comments to steer it",
  "license": "MIT",
  "author": "ZackarySantana",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ZackarySantana/opcode.git",
    "directory": "plugins/review"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "code-review",
    "diff",
    "lsp",
    "agent"
  ],
  "engines": {
    "opencode": "^2.2.0"
  },
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/types/plugins/review/src/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/types/plugins/review/src/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/types/plugins/review/src/tui.d.ts",
      "import": "./dist/tui.js",
      "default": "./dist/tui.js"
    },
    "./rpc": {
      "types": "./dist/types/plugins/review/src/rpc.d.ts",
      "import": "./dist/rpc.js",
      "default": "./dist/rpc.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "dependencies": {
    "@opencode/plugin": "2.2.0",
    "@opencode/client": "2.2.0",
    "@opencode/schema": "2.2.0",
    "@opencode/theme": "2.2.0"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.7.0 <1",
    "@opentui/solid": ">=0.7.0 <1",
    "solid-js": ">=1.9.12 <2"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  }
}
